/*
 * ADVERSARIAL TESTER — properties lens.
 *
 * Random hands (2-10 players, random seat layouts, dead buttons / dead small
 * blinds / heads-up, random stacks, blinds and antes of every type, random
 * legal actions incl. all-ins and timeouts) generated by fast-check. After
 * EVERY step the state is checked with the engine's invariants AND with
 * independent checks (adversarial-eval-reference.ts): chip conservation,
 * card uniqueness, plain-JSON state, purity on deep-frozen inputs, legal
 * action boundaries, dealing order, forced-bet amounts, first actor, phase
 * transitions, and at the end the full payout recomputed from scratch
 * (independent side pots, independent evaluator, odd-chip rule, reveal rule).
 * Determinism: every hand is replayed and must reproduce identical states and
 * events, both from the original and from JSON round-tripped states.
 */
import { CANONICAL_DECK, HAND_PHASE_TRANSITIONS } from '@jpb/shared-types';
import type {
  AnteType,
  CardCode,
  HandEvent,
  HandPhase,
  LegalActions,
  PlayerActionIntent,
  SeatIndex,
} from '@jpb/shared-types';
import fc from 'fast-check';
import { describe, expect, it } from 'vitest';
import { applyAction, checkHandInvariants, createHand, currentPots, getLegalActions, timeoutIntent } from '../src';
import type { CreateHandInput, HandState, HandTransition } from '../src';
import { cmpRef, deepFreeze, refBest, refClockwise, refDeal, refPots, refSplit } from './adversarial-eval-reference';
import type { RefValue } from './adversarial-eval-reference';

type Ev<K extends HandEvent['kind']> = Extract<HandEvent, { kind: K }>;

// ---------------------------------------------------------------------------
// generators

const stackArb = (bb: number): fc.Arbitrary<number> =>
  fc.oneof(
    { weight: 2, arbitrary: fc.integer({ min: 1, max: Math.max(1, 2 * bb) }) }, // all-in from forced bets
    { weight: 2, arbitrary: fc.integer({ min: 1, max: 10 * bb }) },
    { weight: 5, arbitrary: fc.integer({ min: 5 * bb, max: 200 * bb }) },
    { weight: 1, arbitrary: fc.constant(1) },
  );

type Layout = 'STANDARD' | 'DEAD_SB' | 'HEADS_UP' | 'ARBITRARY';

const configArb: fc.Arbitrary<CreateHandInput> = fc
  .record({
    n: fc.integer({ min: 2, max: 10 }),
    extraSeats: fc.integer({ min: 0, max: 8 }),
    seatPerm: fc.array(fc.nat(), { minLength: 10, maxLength: 10 }),
    bb: fc.constantFrom(1, 2, 5, 10, 20, 100, 400),
    sbMode: fc.constantFrom('HALF', 'HALF', 'HALF', 'ZERO', 'EQUAL', 'RANDOM'),
    sbRand: fc.nat(),
    anteType: fc.constantFrom<AnteType>('NONE', 'BB_ANTE', 'ALL_PLAYERS'),
    anteRand: fc.nat(),
    buttonRand: fc.nat(),
    layout: fc.constantFrom<Layout>('STANDARD', 'STANDARD', 'STANDARD', 'DEAD_SB', 'HEADS_UP', 'ARBITRARY'),
    posRand: fc.array(fc.nat(), { minLength: 2, maxLength: 2 }),
    deck: fc.shuffledSubarray([...CANONICAL_DECK], { minLength: 52, maxLength: 52 }),
    stackSeeds: fc.array(fc.nat(), { minLength: 10, maxLength: 10 }),
  })
  .chain((r) =>
    fc.tuple(...Array.from({ length: r.n }, () => stackArb(r.bb))).map((stacks) => {
      const maxSeats = Math.min(10, r.n + r.extraSeats);
      const pool = Array.from({ length: maxSeats }, (_, i) => i);
      const seats: number[] = [];
      for (let i = 0; i < r.n; i++) seats.push(pool.splice((r.seatPerm[i] as number) % pool.length, 1)[0] as number);
      seats.sort((a, b) => a - b);
      const smallBlind =
        r.sbMode === 'HALF'
          ? Math.floor(r.bb / 2)
          : r.sbMode === 'ZERO'
            ? 0
            : r.sbMode === 'EQUAL'
              ? r.bb
              : r.sbRand % (r.bb + 1);
      const ante = r.anteType === 'NONE' ? 0 : r.anteRand % (2 * r.bb + 1);
      let buttonSeat = r.buttonRand % maxSeats; // may be empty (dead button)
      let smallBlindSeat: number | null;
      let bigBlindSeat: number;
      const layout: Layout = r.n === 2 && r.layout !== 'ARBITRARY' ? 'HEADS_UP' : r.layout;
      if (layout === 'HEADS_UP' && r.n === 2) {
        buttonSeat = seats[r.buttonRand % 2] as number;
        smallBlindSeat = buttonSeat;
        bigBlindSeat = seats.find((s) => s !== buttonSeat) as number;
      } else if (layout === 'ARBITRARY' || layout === 'HEADS_UP') {
        bigBlindSeat = seats[(r.posRand[0] as number) % seats.length] as number;
        const others = seats.filter((s) => s !== bigBlindSeat);
        smallBlindSeat =
          (r.posRand[1] as number) % 4 === 0 ? null : (others[(r.posRand[1] as number) % others.length] as number);
      } else {
        const order = refClockwise(seats, buttonSeat, maxSeats);
        // with an occupied button and 2 players the "first after button" is the other player
        smallBlindSeat = layout === 'DEAD_SB' ? null : (order[0] as number);
        bigBlindSeat = (layout === 'DEAD_SB' ? order[0] : order[1]) as number;
        if (bigBlindSeat === smallBlindSeat) smallBlindSeat = null;
      }
      const input: CreateHandInput = {
        handId: `ADV:${seats.join('-')}`,
        handNumber: (r.stackSeeds[0] as number) % 1000,
        maxSeats,
        // given in a scrambled order: "any order" is allowed by the contract
        seats: seats
          .map((seat, i) => ({ seat, playerId: `pl-${seat}`, stack: stacks[i] as number }))
          .sort((a, b) => ((a.seat * 7 + 3) % 11) - ((b.seat * 7 + 3) % 11)),
        buttonSeat,
        smallBlindSeat,
        bigBlindSeat,
        smallBlind,
        bigBlind: r.bb,
        ante,
        anteType: r.anteType,
        deck: r.deck as CardCode[],
      };
      return input;
    }),
  );

/** Picks a legal intent from the legal actions using entropy `e`. */
function pickIntent(legal: LegalActions, e: number, e2: number): PlayerActionIntent {
  const opts: PlayerActionIntent[] = [{ type: 'FOLD' }];
  if (legal.canCheck) opts.push({ type: 'CHECK' }, { type: 'CHECK' }, { type: 'CHECK' });
  if (legal.canCall) opts.push({ type: 'CALL' }, { type: 'CALL' }, { type: 'CALL' });
  const span = legal.maxTo - legal.minTo;
  const sized = [legal.minTo, legal.maxTo, legal.minTo + (span > 0 ? e2 % (span + 1) : 0)];
  if (legal.canBet) for (const a of sized) opts.push({ type: 'BET', amount: a });
  if (legal.canRaise) for (const a of sized) opts.push({ type: 'RAISE', amount: a });
  if (legal.canAllIn) opts.push({ type: 'ALL_IN' }, { type: 'ALL_IN' });
  return opts[e % opts.length] as PlayerActionIntent;
}

// ---------------------------------------------------------------------------
// per-step checks

function allCardsOf(s: HandState): string[] {
  const out: string[] = [...s.deck, ...s.board, ...s.burns];
  for (const p of s.players) if (p.holeCards) out.push(...p.holeCards);
  return out;
}

function checkStep(input: CreateHandInput, s: HandState, tr: HandTransition): void {
  expect(checkHandInvariants(s)).toEqual([]);
  // plain JSON (no undefined, no class instances, no NaN)
  expect(JSON.parse(JSON.stringify(s))).toStrictEqual(s);
  // currentPots (used by views) accounts for every chip in the pot
  if (s.phase !== 'HAND_COMPLETE') {
    const cp = currentPots(s);
    expect(cp.pots.reduce((a, p) => a + p.amount, 0) + (cp.uncalled?.amount ?? 0)).toBe(s.pot);
    for (const pot of cp.pots)
      for (const seat of pot.eligibleSeats) expect(s.players.find((p) => p.seat === seat)?.folded).toBe(false);
  }
  // chips conserved and integral
  const start = input.seats.reduce((a, x) => a + x.stack, 0);
  expect(s.players.reduce((a, p) => a + p.stack, 0) + s.pot).toBe(start);
  for (const p of s.players) {
    expect(Number.isSafeInteger(p.stack) && p.stack >= 0).toBe(true);
  }
  // cards: exactly the 52 distinct cards
  const cards = allCardsOf(s);
  expect(cards).toHaveLength(52);
  expect(new Set(cards).size).toBe(52);
  // externally visible phase is a betting phase (with an actor) or HAND_COMPLETE
  if (s.phase === 'HAND_COMPLETE') {
    expect(s.actingSeat).toBeNull();
    expect(getLegalActions(s)).toBeNull();
    expect(tr.events[tr.events.length - 1]?.kind).toBe('HAND_COMPLETED');
  } else {
    expect(['PREFLOP', 'FLOP', 'TURN', 'RIVER']).toContain(s.phase);
    const last = tr.events[tr.events.length - 1] as Ev<'TURN_TO_ACT'>;
    expect(last.kind).toBe('TURN_TO_ACT');
    expect(last.seat).toBe(s.actingSeat);
    expect(last.legal).toEqual(getLegalActions(s));
    const actor = s.players.find((p) => p.seat === s.actingSeat);
    expect(actor && !actor.folded && !actor.allIn && actor.stack > 0).toBe(true);
  }
}

/** Probes the boundaries of the legal actions on a deep-frozen state (rejections must not mutate). */
function probeLegal(s: HandState): void {
  const legal = getLegalActions(s) as LegalActions;
  const seat = legal.seat;
  const me = s.players.find((p) => p.seat === seat);
  if (!me) throw new Error('acting seat not in hand');
  // independent arithmetic
  const toCall = Math.max(0, s.currentBet - me.streetContribution);
  expect(legal.callAmount).toBe(Math.min(toCall, me.stack));
  expect(legal.allInTo).toBe(me.streetContribution + me.stack);
  expect(legal.canCheck).toBe(toCall === 0);
  expect(legal.canCall).toBe(toCall > 0);
  expect(legal.canFold).toBe(true);
  expect(legal.canBet).toBe(s.currentBet === 0);
  if (legal.canRaise) {
    expect(legal.minTo).toBe(Math.min(s.currentBet + s.minRaiseIncrement, legal.allInTo));
    expect(legal.maxTo).toBe(legal.allInTo);
  }
  if (legal.canBet) {
    expect(legal.minTo).toBe(Math.min(s.bigBlind, legal.allInTo));
    expect(legal.maxTo).toBe(legal.allInTo);
  }
  const ok = (i: unknown): boolean => applyAction(s, seat, i as PlayerActionIntent).ok;
  const code = (i: unknown): string | null => {
    const r = applyAction(s, seat, i as PlayerActionIntent);
    return r.ok ? null : r.code;
  };
  expect(ok({ type: 'FOLD' })).toBe(true);
  expect(ok({ type: 'CHECK' })).toBe(legal.canCheck);
  expect(ok({ type: 'CALL' })).toBe(legal.canCall);
  expect(ok({ type: 'ALL_IN' })).toBe(legal.canAllIn);
  const kind = legal.canBet ? 'BET' : 'RAISE';
  if (legal.canBet || legal.canRaise) {
    expect(ok({ type: kind, amount: legal.minTo })).toBe(true);
    expect(ok({ type: kind, amount: legal.maxTo })).toBe(true);
    expect(code({ type: kind, amount: legal.minTo - 1 })).toBe('AMOUNT_BELOW_MINIMUM');
    expect(code({ type: kind, amount: legal.maxTo + 1 })).toBe('AMOUNT_ABOVE_MAXIMUM');
    expect(code({ type: kind, amount: legal.minTo + 0.5 })).toBe('AMOUNT_NOT_INTEGER');
    expect(code({ type: kind })).toBe('AMOUNT_REQUIRED');
  } else {
    expect(ok({ type: 'BET', amount: legal.allInTo })).toBe(false);
    expect(ok({ type: 'RAISE', amount: legal.allInTo })).toBe(false);
  }
  // other seats cannot act
  for (const p of s.players) {
    if (p.seat === seat) continue;
    expect(applyAction(s, p.seat, { type: 'FOLD' }).ok).toBe(false);
  }
  expect(applyAction(s, s.maxSeats + 3, { type: 'FOLD' }).ok).toBe(false);
}

// ---------------------------------------------------------------------------
// whole-hand checks

/** Phase sequence implied by the events. */
function phaseTrail(events: HandEvent[]): HandPhase[] {
  const out: HandPhase[] = [];
  const push = (p: HandPhase): void => {
    if (out[out.length - 1] !== p) out.push(p);
  };
  for (const e of events) {
    if (e.kind === 'HAND_STARTED') push('HAND_CREATED');
    else if (e.kind === 'HOLE_CARDS_DEALT') push('DEAL_HOLE_CARDS');
    else {
      if (out[out.length - 1] === 'DEAL_HOLE_CARDS') push('PREFLOP');
      if (e.kind === 'STREET_STARTED') push(e.street);
      else if (e.kind === 'SHOWDOWN') push('SHOWDOWN');
      else if (e.kind === 'POT_AWARDED') push('POT_DISTRIBUTION');
      else if (e.kind === 'HAND_COMPLETED') {
        push('POT_DISTRIBUTION');
        push('HAND_COMPLETE');
      }
    }
  }
  return out;
}

function checkPhases(events: HandEvent[]): void {
  const trail = phaseTrail(events);
  expect(trail.slice(0, 3)).toEqual(['HAND_CREATED', 'DEAL_HOLE_CARDS', 'PREFLOP']);
  for (let i = 1; i < trail.length; i++) {
    const from = trail[i - 1] as HandPhase;
    const to = trail[i] as HandPhase;
    if (!HAND_PHASE_TRANSITIONS[from].includes(to))
      throw new Error(`illegal transition ${from} -> ${to}: ${trail.join(' > ')}`);
  }
  expect(trail[trail.length - 1]).toBe('HAND_COMPLETE');
}

function checkForcedBetsAndDeal(input: CreateHandInput, events: HandEvent[]): void {
  const stacks = new Map(input.seats.map((s) => [s.seat, s.stack]));
  const seats = input.seats.map((s) => s.seat);
  const anteActive = input.anteType !== 'NONE' && input.ante > 0;
  const expected: Array<{ seat: number; betType: string; amount: number }> = [];
  const post = (seat: number, betType: string, want: number): void => {
    const st = stacks.get(seat) as number;
    const amt = Math.min(want, st);
    if (amt > 0) {
      stacks.set(seat, st - amt);
      expected.push({ seat, betType, amount: amt });
    }
  };
  if (anteActive && input.anteType === 'ALL_PLAYERS') {
    // every dealt-in player antes; order documented as dealing order
    for (const seat of refClockwise(seats, input.buttonSeat, input.maxSeats)) post(seat, 'ANTE', input.ante);
  } else if (anteActive && input.anteType === 'BB_ANTE') {
    const st = stacks.get(input.bigBlindSeat) as number;
    post(input.bigBlindSeat, 'ANTE', Math.min(input.ante, st - Math.min(input.bigBlind, st)));
  }
  if (input.smallBlindSeat !== null) post(input.smallBlindSeat, 'SMALL_BLIND', input.smallBlind);
  post(input.bigBlindSeat, 'BIG_BLIND', input.bigBlind);
  const forced = events.filter((e): e is Ev<'FORCED_BET_POSTED'> => e.kind === 'FORCED_BET_POSTED');
  expect(forced.map((f) => ({ seat: f.seat, betType: f.betType, amount: f.amount }))).toEqual(expected);
  // all forced bets come right after HAND_STARTED, before any hole card
  const kinds = events.map((e) => e.kind);
  expect(kinds[0]).toBe('HAND_STARTED');
  expect(kinds.slice(1, 1 + forced.length).every((k) => k === 'FORCED_BET_POSTED')).toBe(true);

  // dealing order (independent)
  const deal = refDeal(input.deck, seats, input.buttonSeat, input.maxSeats);
  const holes = events.filter((e): e is Ev<'HOLE_CARDS_DEALT'> => e.kind === 'HOLE_CARDS_DEALT');
  expect(holes.map((h) => h.seat)).toEqual(deal.holeOrder);
  for (const h of holes) expect(h.cards).toEqual(deal.hole.get(h.seat));
  expect(kinds.slice(1 + forced.length, 1 + forced.length + holes.length).every((k) => k === 'HOLE_CARDS_DEALT')).toBe(
    true,
  );
  // streets in order with the right cards
  const streets = events.filter((e): e is Ev<'STREET_STARTED'> => e.kind === 'STREET_STARTED');
  const sizes = { FLOP: [0, 3], TURN: [3, 4], RIVER: [4, 5] } as const;
  expect(streets.map((x) => x.street)).toEqual((['FLOP', 'TURN', 'RIVER'] as const).slice(0, streets.length));
  for (const st of streets) {
    const [a, b] = sizes[st.street as 'FLOP' | 'TURN' | 'RIVER'];
    expect(st.newCards).toEqual(deal.board.slice(a, b));
    expect(st.board).toEqual(deal.board.slice(0, b));
  }
}

/** First actor of each betting round (rule 4), independently. */
function checkFirstActors(input: CreateHandInput, events: HandEvent[]): void {
  const seats = input.seats.map((s) => s.seat);
  const stack = new Map(input.seats.map((s) => [s.seat, s.stack]));
  const folded = new Set<number>();
  let street: string = 'PREFLOP';
  let awaitingFirst = true;
  for (const e of events) {
    if (e.kind === 'FORCED_BET_POSTED' || e.kind === 'PLAYER_ACTED') {
      stack.set(e.seat, e.stack);
      if (e.kind === 'PLAYER_ACTED' && e.action === 'FOLD') folded.add(e.seat);
    } else if (e.kind === 'STREET_STARTED') {
      street = e.street;
      awaitingFirst = true;
    } else if (e.kind === 'TURN_TO_ACT' && awaitingFirst) {
      awaitingFirst = false;
      const from = street === 'PREFLOP' ? input.bigBlindSeat : input.buttonSeat;
      const canAct = refClockwise(seats, from, input.maxSeats).filter(
        (s) => !folded.has(s) && (stack.get(s) as number) > 0,
      );
      expect(e.seat, `first actor on ${street}`).toBe(canAct[0]);
    }
  }
}

/** Recomputes the payout from scratch and compares with the engine's result. */
function checkPayout(input: CreateHandInput, s: HandState, events: HandEvent[]): void {
  const res = s.result;
  if (!res) throw new Error('no result');
  const live = s.players.filter((p) => !p.folded);
  expect(live.length).toBeGreaterThanOrEqual(1);
  const bbAnte = s.anteType === 'BB_ANTE';
  // contributions before the uncalled return
  const contribs = s.players.map((p) => ({
    seat: p.seat,
    folded: p.folded,
    amount: p.totalContribution + p.uncalledReturned - (bbAnte ? p.anteContribution : 0),
  }));
  const dead = bbAnte ? s.players.reduce((a, p) => a + p.anteContribution, 0) : 0;
  const ref = refPots(contribs, dead);
  expect(res.uncalled ? { seat: res.uncalled.seat, amount: res.uncalled.amount } : null).toEqual(ref.uncalled);
  // awarded last side pot first
  const awarded = [...res.pots].reverse();
  expect(awarded.map((p) => ({ amount: p.amount, eligible: p.eligibleSeats }))).toEqual(ref.pots);
  expect(res.pots.map((p) => p.potIndex)).toEqual(ref.pots.map((_, i) => i).reverse());

  const showdown = live.length >= 2;
  expect(res.winType).toBe(showdown ? 'SHOWDOWN' : 'FOLD');
  if (showdown) expect(s.board).toHaveLength(5);
  const values = new Map<number, RefValue>();
  if (showdown) for (const p of live) values.set(p.seat, refBest([...(p.holeCards as string[]), ...s.board]));

  const expectedWon = new Map<number, number>(s.players.map((p) => [p.seat, 0]));
  ref.pots.forEach((pot, i) => {
    let winners: number[];
    if (pot.eligible.length === 1) winners = [...pot.eligible];
    else {
      let best: RefValue | null = null;
      winners = [];
      for (const seat of pot.eligible) {
        const v = values.get(seat) as RefValue;
        const c = best === null ? 1 : cmpRef(v, best);
        if (c > 0) {
          best = v;
          winners = [seat];
        } else if (c === 0) winners.push(seat);
      }
    }
    const split = refSplit(pot.amount, winners, s.buttonSeat, s.maxSeats);
    const got = awarded[i];
    if (!got) throw new Error('missing pot');
    expect(got.winners.map((w) => [w.seat, w.amount])).toEqual([...split.entries()]);
    for (const w of got.winners) {
      expect(w.oddChips).toBe(w.amount - Math.floor(pot.amount / winners.length));
      expect(s.players.find((p) => p.seat === w.seat)?.folded).toBe(false);
    }
    for (const [seat, amt] of split) expectedWon.set(seat, (expectedWon.get(seat) as number) + amt);
    // winningHand describes the winners' hand for contested pots only
    if (pot.eligible.length >= 2) {
      const wv = values.get(winners[0] as number) as RefValue;
      expect(got.winningHand).not.toBeNull();
      expect(cmpRef(refBest(got.winningHand?.bestFive ?? []), wv)).toBe(0);
    } else {
      expect(got.winningHand).toBeNull();
    }
  });
  for (const p of s.players) {
    expect(p.won, `won seat ${p.seat}`).toBe(expectedWon.get(p.seat));
    if (p.folded) expect(p.won).toBe(0);
    expect(p.stack).toBe(p.startingStack - p.totalContribution + p.won);
  }
  expect(res.totalPot).toBe(ref.pots.reduce((a, p) => a + p.amount, 0));
  expect(res.finalStacks).toEqual(s.players.map((p) => ({ seat: p.seat, playerId: p.playerId, stack: p.stack })));
  expect(res.bustedSeats).toEqual(s.players.filter((p) => p.stack === 0).map((p) => p.seat));

  // ---- reveal rule (11), independently
  const sd = events.filter((e): e is Ev<'SHOWDOWN'> => e.kind === 'SHOWDOWN');
  if (!showdown) {
    expect(sd).toHaveLength(0);
    expect(res.reveals).toEqual([]);
    return;
  }
  expect(sd).toHaveLength(1);
  const reveals = (sd[0] as Ev<'SHOWDOWN'>).reveals;
  expect(reveals).toEqual(res.reveals);
  // betting closed before the river action <=> no TURN_TO_ACT after the river was dealt
  const riverIdx = events.findIndex((e) => e.kind === 'STREET_STARTED' && e.street === 'RIVER');
  const riverAction = riverIdx >= 0 && events.slice(riverIdx).some((e) => e.kind === 'TURN_TO_ACT');
  const liveSeats = live.map((p) => p.seat);
  const clockwise = refClockwise(liveSeats, s.buttonSeat, s.maxSeats);
  if (!riverAction) {
    expect(s.allInRunOut).toBe(true);
    expect(reveals.map((r) => r.seat)).toEqual(clockwise);
    expect(reveals.every((r) => !r.mucked && r.cards !== null)).toBe(true);
  } else {
    expect(s.allInRunOut).toBe(false);
    // last aggressor on the river shows first, else first live seat after the button
    let riverAggressor: number | null = null;
    for (const e of events.slice(riverIdx)) {
      if (e.kind === 'PLAYER_ACTED' && (e.action === 'BET' || e.action === 'RAISE')) riverAggressor = e.seat;
    }
    const first =
      riverAggressor !== null && liveSeats.includes(riverAggressor) ? riverAggressor : (clockwise[0] as number);
    const k = clockwise.indexOf(first);
    const order = [...clockwise.slice(k), ...clockwise.slice(0, k)];
    expect(reveals.map((r) => r.seat)).toEqual(order);
    const contested = ref.pots.filter((p) => p.eligible.length >= 2);
    const shown: number[] = [];
    for (const r of reveals) {
      const v = values.get(r.seat) as RefValue;
      const mustShow =
        shown.length === 0 ||
        contested.some(
          (pot) =>
            pot.eligible.includes(r.seat) &&
            pot.eligible.filter((x) => shown.includes(x)).every((x) => cmpRef(values.get(x) as RefValue, v) <= 0),
        );
      expect(r.mucked, `seat ${r.seat} muck decision`).toBe(!mustShow);
      if (mustShow) shown.push(r.seat);
    }
  }
  for (const r of reveals) {
    const p = s.players.find((x) => x.seat === r.seat);
    if (r.mucked) {
      expect(r.cards).toBeNull();
      expect(r.hand).toBeNull();
    } else {
      expect(r.cards).toEqual(p?.holeCards);
      expect(cmpRef(refBest([...(r.cards ?? []), ...s.board]), values.get(r.seat) as RefValue)).toBe(0);
      expect(r.hand?.description).toBeTypeOf('string');
    }
  }
  // every pot winner of a contested pot is revealed
  for (const pot of res.pots) {
    if (pot.eligibleSeats.length < 2) continue;
    for (const w of pot.winners) expect(reveals.find((r) => r.seat === w.seat)?.mucked).toBe(false);
  }
  // evaluated (server-side) contains every live player's hand
  expect(res.evaluated.map((e) => e.seat)).toEqual(liveSeats);
}

function checkEventOrder(events: HandEvent[]): void {
  const kinds = events.map((e) => e.kind);
  const lastIdx = (k: string): number => kinds.lastIndexOf(k as HandEvent['kind']);
  const firstIdx = (k: string): number => kinds.indexOf(k as HandEvent['kind']);
  expect(kinds.filter((k) => k === 'HAND_STARTED')).toHaveLength(1);
  expect(kinds.filter((k) => k === 'HAND_COMPLETED')).toHaveLength(1);
  expect(kinds[kinds.length - 1]).toBe('HAND_COMPLETED');
  const tail = ['UNCALLED_BET_RETURNED', 'SHOWDOWN', 'POT_AWARDED'];
  const lastAction = Math.max(lastIdx('PLAYER_ACTED'), lastIdx('STREET_STARTED'), lastIdx('HOLE_CARDS_DEALT'));
  for (const k of tail) if (firstIdx(k) >= 0) expect(firstIdx(k)).toBeGreaterThan(lastAction);
  if (firstIdx('UNCALLED_BET_RETURNED') >= 0 && firstIdx('SHOWDOWN') >= 0) {
    expect(firstIdx('UNCALLED_BET_RETURNED')).toBeLessThan(firstIdx('SHOWDOWN'));
  }
  if (firstIdx('SHOWDOWN') >= 0 && firstIdx('POT_AWARDED') >= 0)
    expect(firstIdx('SHOWDOWN')).toBeLessThan(firstIdx('POT_AWARDED'));
  expect(kinds.filter((k) => k === 'UNCALLED_BET_RETURNED').length).toBeLessThanOrEqual(1);
  // every TURN_TO_ACT is answered by exactly one PLAYER_ACTED from that seat
  for (let i = 0; i < events.length; i++) {
    const e = events[i] as HandEvent;
    if (e.kind === 'TURN_TO_ACT') {
      const next = events[i + 1] as HandEvent | undefined;
      if (next !== undefined) {
        expect(next.kind).toBe('PLAYER_ACTED');
        expect((next as Ev<'PLAYER_ACTED'>).seat).toBe(e.seat);
      }
    }
    if (e.kind === 'PLAYER_ACTED') expect((events[i - 1] as HandEvent).kind).toBe('TURN_TO_ACT');
  }
}

// ---------------------------------------------------------------------------
// the driver

interface Played {
  states: HandState[];
  events: HandEvent[];
  steps: Array<{ seat: SeatIndex; intent: PlayerActionIntent; timeout: boolean }>;
}

function play(input: CreateHandInput, entropy: number[], probe: boolean): Played {
  const frozenInput = deepFreeze(structuredClone(input));
  const t = createHand(frozenInput);
  expect(t.ok).toBe(true);
  checkStep(input, t.state, t);
  const states = [t.state];
  const events = [...t.events];
  const steps: Played['steps'] = [];
  let s = t.state;
  let k = 0;
  while (s.phase !== 'HAND_COMPLETE') {
    if (steps.length > 400) throw new Error('hand does not terminate');
    deepFreeze(s);
    if (probe) probeLegal(s);
    const legal = getLegalActions(s) as LegalActions;
    const e1 = entropy[k++ % entropy.length] as number;
    const e2 = entropy[k++ % entropy.length] as number;
    const timeout = e1 % 23 === 0;
    const intent = timeout ? timeoutIntent(s) : pickIntent(legal, e1, e2);
    if (timeout) expect(intent).toEqual(legal.canCheck ? { type: 'CHECK' } : { type: 'FOLD' });
    const r = applyAction(s, legal.seat, intent, { timeout });
    if (!r.ok) throw new Error(`legal intent rejected ${JSON.stringify(intent)}: ${r.code}`);
    // the acted event reflects the timeout flag
    const acted = r.events.find((x) => x.kind === 'PLAYER_ACTED') as Ev<'PLAYER_ACTED'>;
    expect(acted.seat).toBe(legal.seat);
    expect(acted.timeout).toBe(timeout);
    steps.push({ seat: legal.seat, intent, timeout });
    s = r.state;
    checkStep(input, s, r);
    states.push(s);
    events.push(...r.events);
  }
  return { states, events, steps };
}

function replay(input: CreateHandInput, steps: Played['steps'], viaJson: boolean): Played {
  const t = createHand(structuredClone(input));
  let s = viaJson ? (JSON.parse(JSON.stringify(t.state)) as HandState) : t.state;
  const states = [t.state];
  const events = [...t.events];
  for (const st of steps) {
    const r = applyAction(s, st.seat, st.intent, { timeout: st.timeout });
    if (!r.ok) throw new Error('replay rejected');
    states.push(r.state);
    events.push(...r.events);
    s = viaJson ? (JSON.parse(JSON.stringify(r.state)) as HandState) : r.state;
  }
  return { states, events, steps };
}

describe('adversarial-eval: random hands (fast-check)', () => {
  it('every step keeps all invariants; payouts, reveals, dealing and phases match independent recomputation', () => {
    let showdowns = 0;
    let splits = 0;
    let sidePots = 0;
    let runOuts = 0;
    fc.assert(
      fc.property(configArb, fc.array(fc.nat(), { minLength: 64, maxLength: 64 }), (input, entropy) => {
        const p = play(input, entropy, true);
        const final = p.states[p.states.length - 1] as HandState;
        checkPhases(p.events);
        checkForcedBetsAndDeal(input, p.events);
        checkFirstActors(input, p.events);
        checkEventOrder(p.events);
        checkPayout(input, final, p.events);
        if (final.result?.winType === 'SHOWDOWN') showdowns++;
        if (final.result?.pots.some((x) => x.winners.length > 1)) splits++;
        if ((final.result?.pots.length ?? 0) > 1) sidePots++;
        if (final.allInRunOut) runOuts++;
        // determinism: identical replay, from live states and from JSON round-trips
        const again = replay(input, p.steps, false);
        expect(again.states).toEqual(p.states);
        expect(again.events).toEqual(p.events);
        const json = replay(input, p.steps, true);
        expect(json.events).toEqual(p.events);
        expect(json.states).toEqual(p.states);
      }),
      { numRuns: Number(process.env.ADV_EVAL_RUNS ?? 1_500), seed: Number(process.env.ADV_EVAL_SEED ?? 0x5eede7a1) },
    );
    expect(showdowns).toBeGreaterThan(150);
    expect(sidePots).toBeGreaterThan(50);
    expect(runOuts).toBeGreaterThan(50);
    expect(splits).toBeGreaterThan(3);
  }, 600_000);

  it('the order of `seats` in the input does not matter (identical states and events)', () => {
    fc.assert(
      fc.property(configArb, fc.array(fc.nat(), { minLength: 32, maxLength: 32 }), (input, entropy) => {
        const reversed: CreateHandInput = { ...input, seats: [...input.seats].reverse() };
        const sorted: CreateHandInput = { ...input, seats: [...input.seats].sort((a, b) => a.seat - b.seat) };
        const a = play(input, entropy, false);
        const b = replay(reversed, a.steps, false);
        const c = replay(sorted, a.steps, false);
        expect(b.states).toEqual(a.states);
        expect(b.events).toEqual(a.events);
        expect(c.events).toEqual(a.events);
      }),
      { numRuns: 300, seed: 2718 },
    );
  }, 300_000);

  it('all-in heavy: everybody shoves or calls — run-outs, many side pots, all hands revealed clockwise', () => {
    fc.assert(
      fc.property(configArb, (input) => {
        const created = createHand(input);
        let s = created.state;
        const all = [...created.events];
        while (s.phase !== 'HAND_COMPLETE') {
          const legal = getLegalActions(s) as LegalActions;
          const intent: PlayerActionIntent = legal.canAllIn
            ? { type: 'ALL_IN' }
            : legal.canCall
              ? { type: 'CALL' }
              : { type: 'CHECK' };
          const r = applyAction(s, legal.seat, intent);
          if (!r.ok) throw new Error(`rejected ${r.code}`);
          s = r.state;
          all.push(...r.events);
          expect(checkHandInvariants(s)).toEqual([]);
        }
        checkPhases(all);
        checkForcedBetsAndDeal(input, all);
        checkEventOrder(all);
        checkPayout(input, s, all);
        expect(s.board).toHaveLength(5);
        expect(s.players.every((p) => !p.folded)).toBe(true);
      }),
      { numRuns: 600, seed: 31337 },
    );
  }, 300_000);

  it('fold-heavy: everyone folds to the last player — no showdown, no further cards, nothing revealed', () => {
    fc.assert(
      fc.property(configArb, (input) => {
        const created = createHand(input);
        let s = created.state;
        const all = [...created.events];
        const boardAtStart = s.board.length;
        while (s.phase !== 'HAND_COMPLETE') {
          const legal = getLegalActions(s) as LegalActions;
          const r = applyAction(s, legal.seat, { type: 'FOLD' });
          if (!r.ok) throw new Error(`rejected ${r.code}`);
          s = r.state;
          all.push(...r.events);
        }
        checkPhases(all);
        checkEventOrder(all);
        checkPayout(input, s, all);
        const live = s.players.filter((p) => !p.folded);
        if (live.length === 1) {
          expect(s.result?.winType).toBe('FOLD');
          expect(s.board).toHaveLength(boardAtStart);
          expect(all.some((e) => e.kind === 'SHOWDOWN')).toBe(false);
          for (const pot of s.result?.pots ?? []) expect(pot.winningHand).toBeNull();
        }
      }),
      { numRuns: 600, seed: 4040 },
    );
  }, 300_000);
});
